// Messe-Hub: rebuilds merge groups from the append-only history table "Messe-Hub Gruppen-Verlauf".
// Rows are never updated or deleted; merging, splitting and ignoring are events, so every step stays traceable and reversible.
function gruppenAusVerlauf(zeilen) {
  const ereignisse = zeilen
    .filter((z) => z && z.gruppe_id && z.aktion)
    .sort((a, b) => (Number(a.id) || 0) - (Number(b.id) || 0) || String(a.zeitpunkt).localeCompare(String(b.zeitpunkt)));
  const liste = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
  const gruppen = new Map();
  const ignoriert = new Set();
  for (const e of ereignisse) {
    const ids = liste(e.lead_ids);
    if (e.aktion === 'zusammengefuehrt') {
      liste(e.ersetzt).forEach((alt) => gruppen.delete(alt));
      gruppen.set(e.gruppe_id, { gruppe_id: e.gruppe_id, lead_ids: ids, haupt_lead_id: ids.includes(e.haupt_lead_id) ? e.haupt_lead_id : ids[0], grund: e.grund || '', von: e.von || '', zeitpunkt: e.zeitpunkt || '' });
    } else if (e.aktion === 'getrennt') {
      gruppen.delete(e.gruppe_id);
    } else if (e.aktion === 'herausgeloest') {
      const g = gruppen.get(e.gruppe_id);
      if (!g) continue;
      g.lead_ids = g.lead_ids.filter((x) => !ids.includes(x));
      if (!g.lead_ids.includes(g.haupt_lead_id)) g.haupt_lead_id = g.lead_ids[0];
      if (g.lead_ids.length < 2) gruppen.delete(e.gruppe_id);
    } else if (e.aktion === 'ignoriert') {
      ignoriert.add(ids.slice().sort().join(','));
    }
  }
  return { gruppen: [...gruppen.values()], ignoriert, ereignisse };
}


// Only the user name of the Basic Auth login is kept (for "von"), never the password.
function benutzer(headers) {
  const h = String((headers && headers.authorization) || '');
  if (!/^Basic\s+/i.test(h)) return '';
  try {
    const roh = h.replace(/^Basic\s+/i, '');
    const text = typeof Buffer !== 'undefined' ? Buffer.from(roh, 'base64').toString('utf8') : atob(roh);
    return text.split(':')[0].slice(0, 80);
  } catch (e) {
    return '';
  }
}

const anfrage = $('Anfrage').first().json;
const body = anfrage.body || {};
const vorhanden = new Set($('Lead-IDs lesen').first().json.ids || []);
const { gruppen } = gruppenAusVerlauf($input.all().map((i) => i.json));
const ID = /^FAIR-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const ids = [...new Set((Array.isArray(body.lead_ids) ? body.lead_ids : []).map(String).filter((x) => ID.test(x)))];
const grund = String(body.grund || '').replace(/\s+/g, ' ').trim().slice(0, 300);
const von = benutzer(anfrage.headers);
const jetzt = new Date().toISOString();
const neueId = 'G-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const abgelehnt = (fehler) => [{ json: { ok: false, fehler } }];
const unbekannt = (liste) => liste.filter((x) => !vorhanden.has(x));

let zeile;
let meldung;
switch (body.aktion) {
  case 'zusammenfuehren': {
    if (ids.length < 2) return abgelehnt('Bitte mindestens zwei Leads auswählen.');
    if (unbekannt(ids).length) return abgelehnt('Unbekannte Lead-ID: ' + unbekannt(ids).join(', '));
    // Leads that already belong to groups pull their whole group into the new one.
    const betroffen = gruppen.filter((g) => g.lead_ids.some((x) => ids.includes(x)));
    const alle = [...new Set([...ids, ...betroffen.flatMap((g) => g.lead_ids)])];
    const haupt = alle.includes(body.haupt_lead_id) ? body.haupt_lead_id : ((betroffen[0] && betroffen[0].haupt_lead_id) || ids[0]);
    zeile = { gruppe_id: neueId, aktion: 'zusammengefuehrt', lead_ids: alle.join(','), haupt_lead_id: haupt, ersetzt: betroffen.map((g) => g.gruppe_id).join(','), grund: grund || 'Im Dashboard zusammengeführt', von, zeitpunkt: jetzt };
    meldung = alle.length + ' Leads wurden zusammengeführt.';
    break;
  }
  case 'trennen': {
    const g = gruppen.find((x) => x.gruppe_id === body.gruppe_id);
    if (!g) return abgelehnt('Diese Gruppe gibt es nicht (mehr).');
    zeile = { gruppe_id: g.gruppe_id, aktion: 'getrennt', lead_ids: g.lead_ids.join(','), haupt_lead_id: g.haupt_lead_id, ersetzt: '', grund: grund || 'Im Dashboard getrennt', von, zeitpunkt: jetzt };
    meldung = 'Gruppe getrennt – die ' + g.lead_ids.length + ' Leads stehen wieder einzeln in der Liste.';
    break;
  }
  case 'herausloesen': {
    const g = gruppen.find((x) => x.gruppe_id === body.gruppe_id);
    const lead = String(body.lead_id || '');
    if (!g || !g.lead_ids.includes(lead)) return abgelehnt('Dieser Lead ist nicht in der Gruppe.');
    zeile = { gruppe_id: g.gruppe_id, aktion: 'herausgeloest', lead_ids: lead, haupt_lead_id: g.haupt_lead_id, ersetzt: '', grund: grund || 'Im Dashboard herausgelöst', von, zeitpunkt: jetzt };
    meldung = g.lead_ids.length <= 2 ? 'Lead herausgelöst – die Gruppe ist damit aufgelöst.' : 'Lead aus der Gruppe herausgelöst.';
    break;
  }
  case 'ignorieren': {
    if (ids.length < 2) return abgelehnt('Ein Vorschlag braucht mindestens zwei Leads.');
    if (unbekannt(ids).length) return abgelehnt('Unbekannte Lead-ID: ' + unbekannt(ids).join(', '));
    zeile = { gruppe_id: neueId, aktion: 'ignoriert', lead_ids: ids.slice().sort().join(','), haupt_lead_id: '', ersetzt: '', grund: grund || 'Kein Duplikat', von, zeitpunkt: jetzt };
    meldung = 'Vorschlag ausgeblendet.';
    break;
  }
  default:
    return abgelehnt('Unbekannte Aktion.');
}

return [{ json: { ok: true, meldung, gruppe_id: zeile.gruppe_id, zeile } }];
